provenance.sourcePrompt:
Opening title card — Osmo masked line reveal style. 6s, 1920x1080, SILENT. Full-screen portrait photo background. Text lines reveal from bottom mask (overflow hidden + translateY). Colors: background text area uses dark overlay, text color #f0ece4 (light on dark photo). No border frame,. Font: Inter or system sans-serif (PP Neue Montreal not available, use Inter)
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#0b0d0e;}
#scene{position:relative;}
/* full-screen portrait — Ken Burns */
#bg{
position:absolute;top:0;left:0;width:100%;height:100%
object-fit:cover;z-index:1
transform-origin:50% 40%
animation:kb 6s linear forwards
}
@keyframes kb{from{transform:scale(1.0)}to{transform:scale(1.05)}}
/* dark gradient
#grad{
position:absolute;bottom:0;left:0;width:65%;height:70%;z-index:2
background:linear-gradient(135deg,rgba(0,0,0,0.82) 0%,transparent 70%)
pointer-events:none
}
#textblock{
position:absolute;bottom:88px;left:88px
z-index:10
}
/* each mask-line: overflow hidden, line height exact */
mask-line{
display:block
overflow:hidden
line-height:1.1
margin-bottom:4px
}
mask-line span{
display:block
transform:translateY(110%)
opacity:0
}
/* typography — Osmo inspired: medium weight, tight tracking */
line-eyebrow span{
font-family:'Inter',Arial,sans-serif
font-size:18px;font-weight:500
letter-spacing:.32em;text-transform:uppercase
color:rgba(240,236,228,0.58)
}
line-name-1 span,.line-name-2 span{
font-family:'Inter',Arial,sans-serif
font-size:88px;font-weight:700
letter-spacing:-.02em;text-transform:uppercase
color:#f0ece4
line-height:.95
}
line-sub span{
font-family:'Inter',Arial,sans-serif
font-size:18px;font-weight:400
letter-spacing:.18em;text-transform:uppercase
color:rgba(240,236,228,0.50)
margin-top:6px;display:block
}
#fade{position:absolute;inset:0;z-index:50;background:#0b0d0e;opacity:0;pointer-events:none;}
</style>
</head>
<body>
<div id="scene">
<img id="bg" src="{{heroImg}}" alt="">
<div id="grad"></div>
<div id="fade"></div>
<div id="textblock">
<div class="mask-line line-eyebrow" id="l0"><span>London · 1976</span></div>
<div class="mask-line line-name-1" id="l1"><span>Benedict</span></div>
<div class="mask-line line-name-2" id="l2"><span>Cumberbatch</span></div>
<div class="mask-line line-sub" id="l3"><span>Stage · Screen · Strange Dimensions</span></div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
/* staggered mask reveal — each line translateY 110%→0 */
tl.to('#l0 span',{y:0,opacity:1,duration:0.72,ease:'power4.out'},0.35)
tl.to('#l1 span',{y:0,opacity:1,duration:0.72,ease:'power4.out'},0.48)
tl.to('#l2 span',{y:0,opacity:1,duration:0.72,ease:'power4.out'},0.61)
tl.to('#l3 span',{y:0,opacity:1,duration:0.6, ease:'power3.out'},0.82)
/* exit — lines retreat back down */
tl.to('#l3 span',{y:'110%',opacity:0,duration:0.45,ease:'power2.in'},5.0)
tl.to('#l2 span',{y:'110%',opacity:0,duration:0.45,ease:'power2.in'},5.1)
tl.to('#l1 span',{y:'110%',opacity:0,duration:0.45,ease:'power2.in'},5.2)
tl.to('#l0 span',{y:'110%',opacity:0,duration:0.45,ease:'power2.in'},5.3)
tl.to('#fade',{opacity:1,duration:0.5,ease:'power2.inOut'},5.4)
})
</script>
</body>
</html>
```
